    foreach($statusFixture in @(@('Cancelled','已取消'),@('Interrupted','曾中斷'))){$phase=[pscustomobject]@{Stage='Restore';Status=$statusFixture[0];ProducedUtc='2026-10-10T00:03:00Z';PayloadGeneration=4;Assistive=[pscustomobject]@{ItemResults=@();FileResults=@()}};$phaseOverview=Get-WsmHtmlOverviewProjection $acceptedCatalog ([pscustomobject]@{Latest=$phase;AllCurrent=@($phase)}) @{one=$true} 'Manager' 11;Check ($phaseOverview.nextStep.action -ceq 'AssistiveReport' -and $phaseOverview.nextStep.reason -match $statusFixture[1]) 'Cancelled/interrupted phase evidence lacked an actionable, status-specific recovery next step.'}
    $channelCatalog=[pscustomobject]@{PairId='pair-channels';DecisionRevision=5;Approval=$null;Source=[pscustomobject]@{HostId='source'};Target=[pscustomobject]@{HostId='target'};Items=@(
        [pscustomobject]@{ItemId='c-item';Name='C item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='C';Adapter='FileScope'}},
        [pscustomobject]@{ItemId='nonc-item';Name='NonC item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='NonC';Adapter='FileScope'}},
        [pscustomobject]@{ItemId='manual-item';Name='Manual item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='C';Adapter='ManualWorkflow'}}
    );Assistive=[pscustomobject]@{Revision=8;Selections=[pscustomobject]@{Revision=3;Items=@([pscustomobject]@{ItemId='c-item';Selected=$true},[pscustomobject]@{ItemId='nonc-item';Selected=$true},[pscustomobject]@{ItemId='manual-item';Selected=$true})};SourceSnapshot=$null;TargetCurrent=$null;Comparison=$null;FileResults=@()}}
    $fileRows=@([pscustomobject]@{ItemId='c-item';Channel='C';RelativePath='one.txt';OriginalPath='C:\\one.txt';PreservedPath='D:\\one.txt';EffectivePath='D:\\one.txt';Status='Applied';ExistingTargetPath='';ExistingTargetHash='';SourceHash='a'*64;ObservedHash='a'*64;Reason='';EntryId='c1';Generation=3;ProjectedGeneration=3},[pscustomobject]@{ItemId='nonc-item';Channel='NonC';RelativePath='two.txt';OriginalPath='C:\\two.txt';PreservedPath='\\target\\share\\two.txt';EffectivePath='';Status='DeferredManual';ExistingTargetPath='';ExistingTargetHash='';SourceHash='b'*64;ObservedHash='';Reason='manual';EntryId='nc1';Generation=3;ProjectedGeneration=3})
    $channelCatalog.Assistive.FileResults=$fileRows
    $channelStage=[pscustomobject]@{Latest=[pscustomobject]@{PayloadGeneration=3;Stage='Restore';Status='Partial';ProducedUtc='2026-10-10T00:00:00Z';Assistive=[pscustomobject]@{ItemResults=@([pscustomobject]@{ItemId='c-item';Pending=$false;Deferred=$false;Status='Applied'},[pscustomobject]@{ItemId='nonc-item';Pending=$true;Deferred=$false;Status='DeferredManual'});FileResults=$fileRows}};AllCurrent=@()}
