        $script:capturedCredentialMap=$null;Set-Item Function:\New-WsmHtmlTargetRestoreChallengeArguments -Value {param($Workspace,$Record,$Jobs,$Secrets,$SessionId,$ContextId,$Takeover)@{Secrets=$Secrets}};Set-Item Function:\Enter-WsmWorkspaceWorkerGuard -Value {throw 'WorkspaceWorkerBusy: injected pre-worker contention'}
