        Check ($script:capturedCredentialMap -and $script:capturedCredentialMap.Count -eq 0) 'Busy worker guard rejection retained materialized secure credentials.'
    }finally{Set-Item Function:\New-WsmHtmlTargetRestoreChallengeArguments -Value $oldResumeArgs;Set-Item Function:\Enter-WsmWorkspaceWorkerGuard -Value $oldEnterWorkerGuard;Set-Item Function:\Clear-WsmHtmlServiceCredentialValues -Value $oldClearCredentials;$script:capturedCredentialMap=$null}
    $cleanupWorkspace=Join-Path ([IO.Path]::GetTempPath()) ('wsm-html-credential-cleanup-'+[Guid]::NewGuid().ToString('N'));[void](Assert-WsmHtmlChallengeTestRoot $cleanupWorkspace 'wsm-html-credential-cleanup-');if([IO.Directory]::Exists($cleanupWorkspace) -or [IO.File]::Exists($cleanupWorkspace)){throw 'Generated HTML credential cleanup test root unexpectedly already exists.'};[void][IO.Directory]::CreateDirectory($cleanupWorkspace)
    try{
        $retryRecord=[pscustomobject]@{jobId=$challengeParent;Status='Running';CompletedUtc=(Get-WsmUtc);canCancel=$true};$retryJob=@{Record=$retryRecord;Path=(Join-Path $cleanupWorkspace 'retry.json')};Set-WsmHtmlCredentialJobWaitingForRetry $retryJob $retryWait;$retryPersisted=Read-WsmJson $retryJob.Path
