        Check ($beginWorker.Disposed -and -not $beginJob.PowerShell -and -not $beginJob.WorkerGuard -and -not $beginJob.SecretCredentials -and $beginCredentials.Count -eq 0) 'BeginInvoke failure retained worker, guard, or secure credential values.'
        $reacquired=Enter-WsmWorkspaceWorkerGuard -Workspace $cleanupWorkspace -Action 'TargetRestore';Exit-WsmWorkspaceWorkerGuard $reacquired
        $writeCredentials=ConvertTo-WsmHtmlServiceCredentials $challengeSecretsBody ([pscustomobject]@{RequiredSecretRefs=@('ServiceSecretA')});$writeGuard=Enter-WsmWorkspaceWorkerGuard -Workspace $cleanupWorkspace -Action 'TargetRestore';$writeWorker=[pscustomobject]@{Disposed=$false};$writeWorker|Add-Member ScriptMethod Dispose {$this.Disposed=$true};$writeJob=@{PowerShell=$writeWorker;WorkerGuard=$writeGuard;SecretCredentials=$writeCredentials;Path=(Join-Path $cleanupWorkspace 'write.json');Record=[pscustomobject]@{status='WaitingForInput'}}
