        try{Set-Item Function:\Write-WsmJson -Value {throw 'injected durable job write failure'};Reject {Write-WsmHtmlCredentialJobAndReleaseRuntime $writeJob} 'Credential waiting-record write fault was not propagated.'}finally{Set-Item Function:\Write-WsmJson -Value $oldWriteJson}
