    Reject {ConvertTo-WsmHtmlServiceCredentials (ConvertFrom-WsmJson ('{"OtherSecret":{"username":"CONTOSO\\svc-app","password":"'+$secretCanary+'"}}')) ([pscustomobject]@{RequiredSecretRefs=@('ServiceSecretA')})} 'HTML credential endpoint accepted a SecretRef outside the durable challenge.'
    Reject {ConvertTo-WsmHtmlServiceCredentials (ConvertFrom-WsmJson ('{"ServiceSecretA":{"username":"CONTOSO\\svc-app","password":"'+$secretCanary+'","extra":"leak"}}')) ([pscustomobject]@{RequiredSecretRefs=@('ServiceSecretA')})} 'HTML credential endpoint accepted an unreviewed credential field.'
